    """Copy horizontal source sequences at isolated matching-color markers."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    sequences = []
    for row in grid:
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            start = c
            while c < w and row[c] != 0:
                c += 1
            if c - start > 1:
                sequences.append(row[start:c])

    # Marker cells are isolated horizontally; a row may contain multiple.
    for r, row in enumerate(grid):
        for col, value in enumerate(row):
            if value == 0:
                continue
            if (col > 0 and row[col - 1] != 0) or (col + 1 < w and row[col + 1] != 0):
                continue
            for seq in sequences:
                if value in seq:
                    start = col - seq.index(value)
                    for i, color in enumerate(seq):
                        x = start + i
                        if 0 <= x < w:
                            out[r][x] = color
                    break
    return out
